create table public.documents (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, class_id uuid references public.classes(id) on delete set null, title text not null, type public.document_type not null default 'lesson_plan', status public.document_status not null default 'draft', content jsonb not null default '{}'::jsonb, model_id text, prompt_version text, estimated_cost numeric(12,6) default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.document_versions (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, version integer not null default 1, content jsonb not null default '{}'::jsonb, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), unique (document_id,version));
create table public.document_sources (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, curriculum_item_id uuid not null references public.curriculum_items(id) on delete cascade, excerpt text, confidence public.confidence_level not null default 'medium', created_at timestamptz not null default now());
create table public.exercises (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, document_id uuid references public.documents(id) on delete set null, title text not null, discipline text not null, level public.school_level not null, difficulty public.exercise_difficulty not null default 'simple', instructions text not null, content jsonb not null default '{}'::jsonb, answer_key jsonb, created_at timestamptz not null default now());
create table public.assessments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, document_id uuid references public.documents(id) on delete set null, title text not null, type public.assessment_type not null default 'formative', discipline text not null, level public.school_level not null, total_points numeric(6,2) not null default 20, rubric jsonb not null default '{}'::jsonb, content jsonb not null default '{}'::jsonb, answer_key jsonb, created_at timestamptz not null default now());
create table public.student_sheets (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, document_id uuid references public.documents(id) on delete set null, title text not null, type public.student_sheet_type not null default 'activity', level public.school_level not null, content jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.progressions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, title text not null, discipline text not null, level public.school_level not null, period text not null, content jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index documents_organization_idx on public.documents(organization_id);
create index documents_owner_idx on public.documents(owner_id);
create index document_versions_document_idx on public.document_versions(document_id);
